<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,text,opts,query,useTask,type DTO} from './shared';import RemoteSelect from './RemoteSelect.vue';import PageState from './PageState.vue';
const route=useRoute(),router=useRouter(),{busy,error,run}=useTask(),kind=ref(String(route.query.kind??'resource')),id=ref(String(route.query.id??'')),depth=ref(Number(route.query.depth)===2?2:1),graph=ref<DTO<'Stage2LocalGraph'>>(),selected=ref<DTO<'Stage2GraphNode'>>(),mode=ref(matchMedia('(max-width:640px)').matches?'list':'graph'),filter=ref(''),search=ref(''),zoom=ref(1),pan=ref({x:0,y:0}),drag=ref<{x:number;y:number;px:number;py:number}>();let controller:AbortController|undefined;
const endpoint=computed(()=>({resource:'/resources',company:'/companies',platform:'/platforms',person:'/people',identity:'/contact-identities'}[kind.value]??'/resources'));
const nodes=computed(()=>graph.value?.nodes.filter(n=>(!filter.value||n.kind===filter.value)&&(!search.value||n.label.toLowerCase().includes(search.value.toLowerCase())))??[]);
const visibleKeys=computed(()=>new Set(nodes.value.map(n=>n.key)));const edges=computed(()=>graph.value?.edges.filter(e=>visibleKeys.value.has(e.source)&&visibleKeys.value.has(e.target))??[]);
const positions=computed(()=>{const result:Record<string,{x:number;y:number}>={};if(!graph.value)return result;result[graph.value.center]={x:500,y:250};const rest=graph.value.nodes.filter(n=>n.key!==graph.value!.center).sort((a,b)=>(a.kind+a.id).localeCompare(b.kind+b.id));let offset=0,ring=0;while(offset<rest.length){const count=Math.min(8+ring*4,rest.length-offset),rx=310+ring*190,ry=160+ring*105;for(let i=0;i<count;i++){const angle=-Math.PI/2+i*Math.PI*2/count;result[rest[offset+i].key]={x:500+Math.cos(angle)*rx,y:250+Math.sin(angle)*ry};}offset+=count;ring++;}return result;});
const height=computed(()=>Math.max(440,...Object.values(positions.value).map(p=>p.y+70)));
function edgeName(e:DTO<'Stage2GraphEdge'>){return e.relation==='owner'&&e.target.startsWith('company:')?'归属主体':text(e.relation);}
function segment(e:DTO<'Stage2GraphEdge'>){const a=positions.value[e.source],b=positions.value[e.target],dx=b.x-a.x,dy=b.y-a.y,t=Math.min(81/Math.abs(dx||.001),26/Math.abs(dy||.001),.45);return {x1:a.x+dx*t,y1:a.y+dy*t,x2:b.x-dx*t,y2:b.y-dy*t};}
function reset(){const points=Object.values(positions.value),xs=points.map(p=>p.x),ys=points.map(p=>p.y);zoom.value=Math.min(1,900/(Math.max(...xs)-Math.min(...xs)+180),400/(Math.max(...ys)-Math.min(...ys)+90));pan.value={x:0,y:0};}
async function load(){controller?.abort();if(!id.value){graph.value=undefined;selected.value=undefined;return;}const params={kind:kind.value,object_id:id.value,depth:depth.value};controller=new AbortController();const signal=controller.signal;await run(async()=>{graph.value=await api.get<DTO<'Stage2LocalGraph'>>('/asset-graph'+query(params),signal);if(signal.aborted||id.value!==params.object_id||kind.value!==params.kind){graph.value=undefined;return;}selected.value=graph.value.nodes.find(n=>n.key===graph.value?.center);reset();await router.replace({path:'/asset-map',query:{kind:params.kind,id:params.object_id,depth:params.depth}});});}
watch(id,load,{immediate:true});watch(depth,load);watch(kind,()=>{id.value='';graph.value=undefined;selected.value=undefined;},{flush:'sync'});onBeforeUnmount(()=>controller?.abort());
function focus(n:DTO<'Stage2GraphNode'>){kind.value=n.kind;id.value=n.id;void load();}
const link=(n:DTO<'Stage2GraphNode'>)=>n.kind==='resource'?'/resources/'+n.id:n.kind==='person'?{path:'/resources',query:{tab:'roles',person_id:n.id}}:`/directory/${n.kind}/${n.id}`;
function start(e:PointerEvent){if(e.target instanceof SVGElement&&e.target.closest('[data-node]'))return;(e.currentTarget as SVGElement).setPointerCapture(e.pointerId);drag.value={x:e.clientX,y:e.clientY,px:pan.value.x,py:pan.value.y};}
function move(e:PointerEvent){if(drag.value)pan.value={x:drag.value.px+(e.clientX-drag.value.x),y:drag.value.py+(e.clientY-drag.value.y)};}
function key(e:KeyboardEvent){const shifts:Record<string,[number,number]>={ArrowLeft:[30,0],ArrowRight:[-30,0],ArrowUp:[0,30],ArrowDown:[0,-30]};if(shifts[e.key]){e.preventDefault();pan.value={x:pan.value.x+shifts[e.key][0],y:pan.value.y+shifts[e.key][1]};}if(e.key==='+'||e.key==='=')zoom.value=Math.min(2.5,zoom.value+.1);if(e.key==='-')zoom.value=Math.max(.15,zoom.value-.1);if(e.key==='0')reset();}
</script>
<template><header class="page-heading"><div><h1>资产地图</h1><p>只读探索当前权限内的已知关联。布局不是必填层级，也不代表已补齐全公司的资产。</p></div><RouterLink to="/resources" class="btn-secondary">返回清单</RouterLink></header><section class="feishu-section"><div class="grid gap-3 border-b p-3 sm:grid-cols-[140px_minmax(160px,1fr)_140px]"><label><span class="admin-form-label">中心对象类型</span><select v-model="kind" class="admin-field"><option v-for="o in opts(['resource','company','identity','platform','person'])" :value="o.value">{{o.label}}</option></select></label><label><span class="admin-form-label">选择中心对象</span><RemoteSelect v-model="id" :endpoint="endpoint" label="地图中心"/></label><label><span class="admin-form-label">展开范围</span><select v-model="depth" class="admin-field"><option :value="1">一层邻接</option><option :value="2">两层邻接</option></select></label></div><PageState :error="error" :busy="busy" @retry="load"/><p v-if="!id" class="p-8 text-center text-sm text-gray-500">先选择一个资源、公司、平台、注册身份或人员，探索它的局部关联。</p><template v-if="graph"><div class="toolbar"><button class="btn-secondary !py-1 text-xs" :aria-pressed="mode==='graph'" @click="mode='graph'">关系图</button><button class="btn-secondary !py-1 text-xs" :aria-pressed="mode==='list'" @click="mode='list'">列表视图</button><input v-model="search" class="feishu-input min-w-0 flex-1" aria-label="筛选当前地图" placeholder="筛选当前结果中的名称"><select v-model="filter" class="feishu-input" aria-label="节点类型筛选"><option value="">所有节点类型</option><option v-for="o in opts(['resource','company','identity','platform','person'])" :value="o.value">{{o.label}}</option></select></div><p class="border-b bg-gray-50 px-3 py-2 text-xs text-gray-500">局部已知关系 · {{nodes.length}} 个当前显示节点 / {{edges.length}} 条当前显示关联；上限 100 节点、200 关联。{{graph.truncated?'已截断，请缩小中心或切换列表继续查阅。':'仅展示当前可见对象，不推断缺失关系。'}}</p><div class="grid min-w-0 lg:grid-cols-[minmax(0,1fr)_260px]"><div class="min-w-0"><div v-if="mode==='graph'" class="relative overflow-hidden bg-gray-50"><div class="absolute left-2 top-2 z-10 flex gap-1"><button class="btn-secondary !px-2 !py-1 text-xs" aria-label="缩小地图" @click="zoom=Math.max(.15,zoom-.15)">−</button><button class="btn-secondary !px-2 !py-1 text-xs" @click="reset">复位</button><button class="btn-secondary !px-2 !py-1 text-xs" aria-label="放大地图" @click="zoom=Math.min(2.5,zoom+.15)">+</button></div><svg class="h-[420px] w-full touch-none" viewBox="0 0 1000 500" role="group" aria-label="资产关系图。方向键平移，加减缩放，0复位；可切换列表视图。" tabindex="0" @keydown="key" @pointerdown="start" @pointermove="move" @pointerup="drag=undefined" @pointercancel="drag=undefined"><defs><marker id="map-arrow" markerWidth="8" markerHeight="8" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#94a3b8"/></marker></defs><g :transform="`translate(${pan.x},${pan.y}) translate(500,250) scale(${zoom}) translate(-500,-250)`"><g v-for="edge in edges" :key="edge.id"><line v-bind="segment(edge)" stroke="#94a3b8" :stroke-dasharray="edge.confirmation==='confirmed'?undefined:'5 4'" marker-end="url(#map-arrow)"/><text v-if="nodes.length<=8||(selected?.key!==graph.center&&(edge.source===selected?.key||edge.target===selected?.key))" :x="(positions[edge.source].x+positions[edge.target].x)/2" :y="(positions[edge.source].y+positions[edge.target].y)/2-6" text-anchor="middle" font-size="10" fill="#64748b">{{edgeName(edge)}}</text></g><g v-for="n in nodes" :key="n.key" data-node :transform="`translate(${positions[n.key].x},${positions[n.key].y})`" role="button" tabindex="0" :aria-label="text(n.kind)+' '+n.label+' '+text(n.verification)" class="cursor-pointer outline-accent-500" @click="selected=n" @keydown.enter.stop="selected=n" @keydown.space.prevent.stop="selected=n"><rect x="-78" y="-23" width="156" height="46" rx="7" :fill="selected?.key===n.key?'#eff6ff':'white'" :stroke="n.key===graph.center?'#3b82f6':'#cbd5e1'" :stroke-width="n.key===graph.center?2:1"/><text y="-4" text-anchor="middle" font-size="11" fill="#1f2937">{{n.label.length>12?n.label.slice(0,12)+'…':n.label}}</text><text y="13" text-anchor="middle" font-size="9" fill="#64748b">{{text(n.kind)}} · {{text(n.verification)}}</text><title>{{n.label}}</title></g></g></svg><p class="px-3 pb-3 text-[11px] text-gray-500">虚线：待确认 · 实线：已确认 · 箭头：关系方向。拖动平移；选中后可继续展开。{{height>750?'节点较多，可拖动查看下方节点或使用列表视图。':''}}</p></div><div v-else class="max-h-[600px] overflow-y-auto"><div v-for="n in nodes" :key="n.key" class="flex items-center justify-between gap-2 border-b p-3 text-xs"><button class="text-link text-left" @click="selected=n">{{n.label}} · {{text(n.kind)}}</button><RouterLink :to="link(n)" class="text-link">详情</RouterLink></div><h3 class="border-b bg-gray-50 p-3 text-xs font-medium">关联方向与状态</h3><p v-for="e in edges" :key="e.id" class="border-b p-3 text-xs">{{graph.nodes.find(n=>n.key===e.source)?.label}} → {{edgeName(e)}} → {{graph.nodes.find(n=>n.key===e.target)?.label}} · {{text(e.confirmation)}}</p></div></div><aside class="border-t bg-white p-4 lg:border-l lg:border-t-0"><template v-if="selected"><p class="text-xs text-gray-500">选中对象</p><h2 class="mt-2 break-words text-base font-semibold">{{selected.label}}</h2><p class="mt-2 text-xs text-gray-500">{{text(selected.kind)}} · {{text(selected.type_code)}} · {{text(selected.verification)}}</p><p v-if="selected.lifecycle" class="mt-2 text-xs">{{text(selected.lifecycle)}}</p><p v-for="d in selected.declarations" :key="d.relation_kind" class="mt-2 text-xs text-amber-700">{{text(d.relation_kind)}}：{{text(d.state)}}</p><div class="mt-4 flex flex-wrap gap-2"><RouterLink :to="link(selected)" class="btn-primary">查看详情</RouterLink><button class="btn-secondary" :disabled="busy" @click="focus(selected)">以此为中心</button></div><p class="mt-4 text-xs leading-5 text-gray-500">地图不维护独立数据；编辑、授权和变更请在统一详情与治理中进行。</p></template></aside></div></template></section></template>
